-- Generated from recovered LIMS/LIMSBasic package buttons.
-- Patches only the first rendered data grid; the PostgreSQL-safe page structure is preserved.
-- target_view_count: 16
-- expected_visible_button_count: 29

CREATE OR REPLACE FUNCTION pg_temp.find_layout_datagrid_path(
    document jsonb,
    current_path text[] DEFAULT ARRAY[]::text[]
) RETURNS text[]
LANGUAGE plpgsql
AS $$
DECLARE
    child_key text;
    child_value jsonb;
    child_index integer := 0;
    found_path text[];
BEGIN
    IF jsonb_typeof(document) = 'object' THEN
        IF document ->> 'type' = 'layoutDatagrid' THEN
            RETURN current_path;
        END IF;
        FOR child_key, child_value IN SELECT key, value FROM jsonb_each(document) LOOP
            found_path := pg_temp.find_layout_datagrid_path(child_value, current_path || child_key);
            IF found_path IS NOT NULL THEN RETURN found_path; END IF;
        END LOOP;
    ELSIF jsonb_typeof(document) = 'array' THEN
        FOR child_value IN SELECT value FROM jsonb_array_elements(document) LOOP
            found_path := pg_temp.find_layout_datagrid_path(child_value, current_path || child_index::text);
            IF found_path IS NOT NULL THEN RETURN found_path; END IF;
            child_index := child_index + 1;
        END LOOP;
    END IF;
    RETURN NULL;
END
$$;

