e_retainState/retained'' && retainState != ''LIMSSample_retainState/retaining'')\n\t\t) {\n\t\t\t//组织选中样品数组\n\t\t\tsampleInfoArr.push(selectData[i]);\n\t\t}\n\t}\n\t\n\tsampleArr = sampleInfoArr;\n\n\n\tif (sampleInfoArr.length > 0) {\n\t\t//simpSamplehandle(简易操作)配置项\n\t\tvar result = ReactAPI.getSystemConfig(\n\t\t\t{\n\t\t\t\tmoduleCode: \"LIMSSample\",\n\t\t\t\tkey: \"LIMSSample.simpSamplehandle\",\n\t\t\t\tprofilescAtive: \"\"\n\t\t\t}\n\t\t)\n\t\tvar simpSamplehandle = result[\"LIMSSample.simpSamplehandle\"];\n\t\t\n\t\t//若配置项为否,则打开样品处理页面,填写处理信息\n\t\tif (simpSamplehandle.indexOf(\"cancelSampleSimple\") === -1) {\n\t\t\tReactAPI.createDialog(\"sampleDealDialog\", {\n\t\t\t\ttitle: ReactAPI.international.getText(\"LIMSSample.viewtitle.sampleDeal.cancelSample\"),\n\t\t\t\turl: \"/msService/LIMSSample/sample/sampleInfo/sampleDealEdit?pageName=sampleDeal_canceled&dgName=LIMSSample_5.0.0.0_sample_sampleDealListLayout_sampleInfo_sdg&btnCode=LIMSSample_5.0.0.0_sample_sampleDealListPart_BUTTON_cancel\",\n\t\t\t\tsize: 2,\n\t\t\t\tisRef: false, // 是否开启参照\n\t\t\t\tbuttons: [\n\t\t\t\t\t{\n\t\t\t\t\t\ttext: ReactAPI.international.getText(\"EditView.operate.button.submit\"),\n\t\t\t\t\t\ttype: \"primary\",\n\t\t\t\t\t\tonClick: function(event) {\n\t\t\t\t\t\t\tevent.ReactAPI.submitFormData(\"save\");\n\t\t\t\t\t\t}\n\t\t\t\t\t},\n\t\t\t\t\t{\n\t\t\t\t\t\ttext: ReactAPI.international.getText(\"Button.text.cancel\"),\n\t\t\t\t\t\ttype: \"cancel\",\n\t\t\t\t\t\tonClick: function(event) {\n\t\t\t\t\t\t\tReactAPI.destroyDialog(\"sampleDealDialog\");\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t]\n\t\t\t});\n\t\t}else{\n\t\t\tvar signatureEnabled = ReactAPI.eSign.signatureEnabled({\n\t\t\t\tbuttonCode: \"LIMSSample_5.0.0.0_sample_sampleDealListPart_BUTTON_cancel\"\n\t\t\t});\n\n\t\t\tif(signatureEnabled){//电子签名启用了\n\t\t\t\t//打开电子签名\n\t\t\t\tReactAPI.eSign.openEsign({\n\t\t\t\t\tbuttonCode: \"LIMSSample_5.0.0.0_sample_sampleDealListPart_BUTTON_cancel\",\n\t\t\t\t\tgetSignLog: function(sig