        ) AS restored(view_code, buttons)
    LOOP
        existing_oid := NULL;
        target_oid := NULL;
        payload_text := NULL;
        IF COALESCE(runtime_json_is_oid, false) THEN
            SELECT view_json INTO existing_oid
            FROM public.runtime_extra_view
            WHERE code = action_view.view_code;
            IF existing_oid IS NOT NULL AND EXISTS (
                SELECT 1 FROM pg_largeobject_metadata WHERE oid = existing_oid
            ) THEN
                payload_text := convert_from(lo_get(existing_oid), 'UTF8');
            END IF;
        ELSE
            EXECUTE 'SELECT view_json::text FROM public.runtime_extra_view WHERE code = $1'
            INTO payload_text USING action_view.view_code;
        END IF;
        IF payload_text IS NULL THEN
            RAISE EXCEPTION 'Runtime view payload not found: %', action_view.view_code;
        END IF;

        payload := payload_text::jsonb;
        grid_path := pg_temp.find_layout_datagrid_path(payload);
        IF grid_path IS NULL THEN
            RAISE EXCEPTION 'Rendered data grid not found: %', action_view.view_code;
        END IF;
        payload := jsonb_set(payload, grid_path || ARRAY['buttons'], action_view.buttons, true);
        payload := jsonb_set(payload, grid_path || ARRAY['isCheckBox'], 'true'::jsonb, true);
        target_text := payload::text;

        IF target_text <> payload_text THEN
            IF COALESCE(runtime_json_is_oid, false) THEN
                target_oid := lo_from_bytea(0, convert_to(target_text, 'UTF8'));
                UPDATE public.runtime_extra_view
                SET view_json = target_oid
                WHERE code = action_view.view_code;
            ELSE
                EXECUTE 'UPDATE public.runtime_extra_view SET view_json = $1 WHERE code = $2'
                USING target_text, action_view.view_code;
            END IF;
        END IF;

        UPDATE public.ec_extra_view
        SET view_json = target_text
        WHERE code = action_view.view_code;
    END LOOP;
END $$;
